44	/**
45	 * Checks the health of a subsystem of Jenkins and if there's something
46	 * that requires administrator's attention, notify the administrator.
47	 *
48	 * <h2>How to implement?</h2>
49	 * <p>
50	 * Plugins who wish to contribute such notifications can implement this
51	 * class and put {@link Extension} on it to register it to Jenkins.
52	 *
53	 * <p>
54	 * Once installed, it's the implementer's responsibility to perform
55	 * monitoring and activate/deactivate the monitor accordingly. Sometimes
56	 * this can be done by updating a flag from code (see {@link SCMTrigger}
57	 * for one such example), while other times it's more convenient to do
58	 * so by running some code periodically (for this, use {@link TimerTrigger#timer})
59	 *
60	 * <p>
61	 * {@link AdministrativeMonitor}s are bound to URL by {@link Jenkins#getAdministrativeMonitor(String)}.
62	 * See {@link #getUrl()}.
63	 *
64	 * <h3>Views</h3>
65	 * <dl>
66	 * <dt>message.jelly</dt>
67	 * <dd>
68	 * If {@link #isActivated()} returns true, Jenkins will use the {@code message.jelly}
69	 * view of this object to render the warning text. This happens in the
70	 * {@code http://SERVER/jenkins/manage} page. This view should typically render
71	 * a DIV box with class='alert alert-danger' or class='alert alert-warning' with a human-readable text
72	 * inside it. It often also contains a link to a page that provides more details
73	 * about the problem.<br>
74	 * Additionally 2 numbers are shown in the Jenkins header of administrators, one with the number or active
75	 * non-security relevant monitors and one with the number of active security relevant monitors.
76	 * </dd>
77	 * </dl>
78	 *
79	 * <h3>Use with System Read permission</h3>
80	 * <p>
81	 *     By default administrative monitors are visible only to users with Administer permission.
82	 *     Users with {@link Jenkins#SYSTEM_READ} permission can access administrative monitors that override {@link #getRequiredPermission()}.
83	 *     Care needs to be taken to ensure users with that permission don't have access to actions modifying system state.
84	 *     For more details, see {@link #getRequiredPermission()}.
85	 * </p>
86	 *
87	 * @author Kohsuke Kawaguchi
88	 * @since 1.273
89	 * @see Jenkins#administrativeMonitors
90	 */
91	@LegacyInstancesAreScopedToHudson
92	public abstract class AdministrativeMonitor extends AbstractModelObject implements ExtensionPoint, StaplerProxy {
93	    /**
94	     * Human-readable ID of this monitor, which needs to be unique within the system.
95	     *
96	     * <p>
97	     * This ID is used to remember persisted setting for this monitor,
98	     * so the ID should remain consistent beyond the Hudson JVM lifespan.
99	     */
100	    public final String id;
101	
102	    protected AdministrativeMonitor(String id) {
103	        this.id = id;
104	    }
105	
106	    protected AdministrativeMonitor() {
107	        this.id = this.getClass().getName();
108	    }
109	
110	    /**
111	     * Returns the URL of this monitor, relative to the context path, like "administrativeMonitor/foobar".
112	     */
113	    public String getUrl() {
114	        return "administrativeMonitor/" + id;
115	    }
116	
117	    @Override
118	    public String getDisplayName() {
119	        return id;
120	    }
121	
122	    @Override
123	    public final String getSearchUrl() {
124	        return getUrl();
125	    }
126	
127	    /**
128	     * Mark this monitor as disabled, to prevent this from showing up in the UI.
129	     */
130	    public void disable(boolean value) throws IOException {
131	        AbstractCIBase jenkins = Jenkins.get();
132	        Set<String> set = jenkins.getDisabledAdministrativeMonitors();
133	        if (value) {
134	            set.add(id);
135	        } else {
136	            set.remove(id);
137	        }
138	        jenkins.setDisabledAdministrativeMonitors(set);
139	        jenkins.save();
140	    }
141	
142	    /**
143	     * Returns true if this monitor {@link #disable(boolean) isn't disabled} earlier.
144	     *
145	     * <p>
146	     * This flag implements the ability for the admin to say "no thank you" to the monitor that
147	     * he wants to ignore.
148	     */
149	    public boolean isEnabled() {
150	        return !Jenkins.get().getDisabledAdministrativeMonitors().contains(id);
151	    }
152	
153	    /**
154	     * Returns true if this monitor is activated and
155	     * wants to produce a warning message.
156	     *
157	     * <p>
158	     * This method is called from the HTML rendering thread,
159	     * so it should run efficiently.
160	     */
161	    public abstract boolean isActivated();
162	
163	    /**
164	     * Returns true if this monitor is security related.
165	     *
166	     * This will be used to determine which icon will be used in the navigation bar.
167	     *
168	     * @since 2.267
169	     */
170	    public boolean isSecurity() {
171	        return false;
172	    }
173	
174	    /**
175	     * URL binding to disable this monitor.
176	     */
177	    @RequirePOST
178	    public void doDisable(StaplerRequest req, StaplerResponse rsp) throws IOException {
179	        Jenkins.get().checkPermission(Jenkins.ADMINISTER);
180	        disable(true);
181	        rsp.sendRedirect2(req.getContextPath() + "/manage");
182	    }
183	
184	    /**
185	     * Required permission to view this admin monitor.
186	     * By default {@link Jenkins#ADMINISTER}, but {@link Jenkins#SYSTEM_READ} is also supported.
187	     * <p>
188	     *     Changing this permission check to return {@link Jenkins#SYSTEM_READ} will make the active
189	     *     administrative monitor appear on {@code manage.jelly} and on the globally visible
190	     *     {@link jenkins.management.AdministrativeMonitorsDecorator} to users without Administer permission.
191	     *     {@link #doDisable(StaplerRequest, StaplerResponse)} will still always require Administer permission.
192	     * </p>
193	     * <p>
194	     *     Implementers need to ensure that {@code doAct} and other web methods perform necessary permission checks:
195	     *     Users with System Read permissions are expected to be limited to read-only access.
196	     *     Form UI elements that change system state, e.g. toggling a feature on or off, need to be hidden from users
197	     *     lacking Administer permission.
198	     * </p>
199	     */
200	    public Permission getRequiredPermission() {
201	        return Jenkins.ADMINISTER;
202	    }
203	
204	    /**
205	     * Ensure that URLs in this administrative monitor are only accessible to users with {@link #getRequiredPermission()}.
206	     */
207	    @Override
208	    @Restricted(NoExternalUse.class)
209	    public Object getTarget() {
210	        Jenkins.get().checkPermission(getRequiredPermission());
211	        return this;
212	    }
213	
214	    /**
215	     * All registered {@link AdministrativeMonitor} instances.
216	     */
217	    public static ExtensionList<AdministrativeMonitor> all() {
218	        return ExtensionList.lookup(AdministrativeMonitor.class);
219	    }
220	}

