208	    @RestrictedSince("2.222")
209	    public static final Predicate<Descriptor> FILTER = input -> input.getCategory() instanceof GlobalConfigurationCategory.Security;
210	
211	    /**
212	     * @see Describable#getDescriptor()
213	     */
214	    @SuppressWarnings("unchecked")
215	    @Override
216	    public Descriptor<GlobalSecurityConfiguration> getDescriptor() {
217	        return Jenkins.get().getDescriptorOrDie(getClass());
218	    }
219	
220	    @Extension @Symbol("security")
221	    public static final class DescriptorImpl extends Descriptor<GlobalSecurityConfiguration> {
222	        @NonNull
223	        @Override
224	        public String getDisplayName() {
225	            return Messages.GlobalSecurityConfiguration_DisplayName();
226	        }
227	    }
228	}

