385	    private static int plainHttpConnection(String url, List<String> args, CLIConnectionFactory factory)
386	            throws GeneralSecurityException, IOException, InterruptedException {
387	        LOGGER.log(FINE, "Trying to connect to {0} via plain protocol over HTTP", url);
388	        if (factory.noCertificateCheck) {
389	            SSLContext sslContext = SSLContext.getInstance("TLS");
390	            sslContext.init(null, new TrustManager[] {new NoCheckTrustManager()}, new SecureRandom());
391	            HttpsURLConnection.setDefaultSSLSocketFactory(sslContext.getSocketFactory());
392	            HttpsURLConnection.setDefaultHostnameVerifier((s, sslSession) -> true);
393	        }
394	        FullDuplexHttpStream streams = new FullDuplexHttpStream(new URL(url), "cli?remoting=false", factory.authorization);
395	        try (ClientSideImpl connection = new ClientSideImpl(new PlainCLIProtocol.FramedOutput(streams.getOutputStream()))) {
396	            connection.start(args);
397	            InputStream is = streams.getInputStream();
398	            if (is.read() != 0) { // cf. FullDuplexHttpService
399	                throw new IOException("expected to see initial zero byte; perhaps you are connecting to an old server which does not support -http?");
400	            }
401	            new PlainCLIProtocol.FramedReader(connection, is).start();
402	            new Thread("ping") { // JENKINS-46659
403	                @Override
404	                public void run() {
405	                    try {
406	                        Thread.sleep(PING_INTERVAL);
407	                        while (!connection.complete) {
408	                            LOGGER.fine("sending ping");
409	                            connection.sendEncoding(Charset.defaultCharset().name()); // no-op at this point
410	                            Thread.sleep(PING_INTERVAL);
411	                        }
412	                    } catch (IOException | InterruptedException x) {
413	                        LOGGER.log(Level.WARNING, null, x);
414	                    }
415	                }
416	
417	            }.start();
418	            return connection.exit();
419	        }
420	    }
