422	    private static final class ClientSideImpl extends PlainCLIProtocol.ClientSide {
423	
424	        volatile boolean complete;
425	        private int exit = -1;
426	
427	        ClientSideImpl(PlainCLIProtocol.Output out) {
428	            super(out);
429	        }
430	
431	        void start(List<String> args) throws IOException {
432	            for (String arg : args) {
433	                sendArg(arg);
434	            }
435	            sendEncoding(Charset.defaultCharset().name());
436	            sendLocale(Locale.getDefault().toString());
437	            sendStart();
438	            new Thread("input reader") {
439	                @Override
440	                public void run() {
441	                    try {
442	                        final OutputStream stdin = streamStdin();
443	                        byte[] buf = new byte[60_000]; // less than 64Kb frame size for WS
444	                        while (!complete) {
445	                            int len = System.in.read(buf);
446	                            if (len == -1) {
447	                                break;
448	                            } else {
449	                                stdin.write(buf, 0, len);
450	                            }
451	                        }
452	                        sendEndStdin();
453	                    } catch (IOException x) {
454	                        LOGGER.log(Level.WARNING, null, x);
455	                    }
456	                }
457	            }.start();
458	        }
459	
460	        @Override
461	        protected synchronized void onExit(int code) {
462	            this.exit = code;
463	            finished();
464	        }
465	
466	        @Override
467	        protected void onStdout(byte[] chunk) throws IOException {
468	            System.out.write(chunk);
469	        }
470	
471	        @Override
472	        protected void onStderr(byte[] chunk) throws IOException {
473	            System.err.write(chunk);
474	        }
475	
476	        @Override
477	        protected void handleClose() {
478	            finished();
479	        }
480	
481	        private synchronized void finished() {
482	            complete = true;
483	            notifyAll();
484	        }
485	
486	        synchronized int exit() throws InterruptedException {
487	            while (!complete) {
488	                wait();
489	            }
490	            return exit;
491	        }
492	
493	    }
