277	        public ContextMenu from(ModelObjectWithContextMenu self, StaplerRequest request, StaplerResponse response, String view) throws JellyException, IOException {
278	            WebApp webApp = WebApp.getCurrent();
279	            final Script s = webApp.getMetaClass(self).getTearOff(JellyClassTearOff.class).findScript(view);
280	            if (s != null) {
281	                JellyFacet facet = webApp.getFacet(JellyFacet.class);
282	                request.setAttribute("taskTags", this); // <l:task> will look for this variable and populate us
283	                request.setAttribute("mode", "side-panel");
284	                // run sidepanel but ignore generated HTML
285	                facet.scriptInvoker.invokeScript(request, response, new Script() {
286	                    @Override
287	                    public Script compile() throws JellyException {
288	                        return this;
289	                    }
290	
291	                    @Override
292	                    public void run(JellyContext context, XMLOutput output) throws JellyTagException {
293	                        Functions.initPageVariables(context);
294	                        s.run(context, output);
295	                    }
296	                }, self, new XMLOutput(new DefaultHandler()));
297	            } else
298	            if (self instanceof Actionable) {
299	                // fallback
300	                this.addAll(((Actionable) self).getAllActions());
301	            }
302	
303	            return this;
304	        }
