22	/**
23	 * Dedicated class to handle the logic related to so-called <em>detached plugins</em>.
24	 *
25	 * <p>Originally, some features were directly in Jenkins core. Over time, more and more features got extracted in dedicated plugins.
26	 * Issue is: many plugins had started depending on these features, that now were not in the core anymore.
27	 * So the chosen design strategy has been that the jenkins.war would embed these plugins, and automatically install them and mark them as optional dependencies.
28	 * This way, older plugins would keep working without having to be modified.</p>
29	 * <p>
30	 * This code was originally moved from {@link ClassicPluginStrategy}.
31	 *
32	 * @since 2.163
33	 */
34	@Restricted(NoExternalUse.class)
35	public class DetachedPluginsUtil {
36	    private static final Logger LOGGER = Logger.getLogger(DetachedPluginsUtil.class.getName());
37	
38	    /**
39	     * Record of which plugins which removed from core and when.
40	     */
41	    @VisibleForTesting
42	    static final List<DetachedPlugin> DETACHED_LIST;
43	
44	    /**
45	     * Implicit dependencies that are known to be unnecessary and which must be cut out to prevent a dependency cycle among bundled plugins.
46	     */
47	    private static final Set<String> BREAK_CYCLES;
48	
49	    static {
50	        try (InputStream is = ClassicPluginStrategy.class.getResourceAsStream("/jenkins/split-plugins.txt")) {
51	            DETACHED_LIST = configLines(is).map(line -> {
52	                String[] pieces = line.split(" ");
53	
54	                return new DetachedPluginsUtil.DetachedPlugin(pieces[0],
55	                                                              pieces[1] + ".*",
56	                                                              pieces[2]);
57	            }).collect(Collectors.toUnmodifiableList());
58	        } catch (IOException x) {
59	            throw new ExceptionInInitializerError(x);
60	        }
61	        try (InputStream is = ClassicPluginStrategy.class.getResourceAsStream("/jenkins/split-plugin-cycles.txt")) {
62	            BREAK_CYCLES = configLines(is).collect(Collectors.toUnmodifiableSet());
63	        } catch (IOException x) {
64	            throw new ExceptionInInitializerError(x);
65	        }
66	    }
67	
68	    private DetachedPluginsUtil() {
69	    }
70	
71	    /**
72	     * Returns all the plugin dependencies that are implicit based on a particular Jenkins version
73	     *
74	     * @since 2.0
75	     */
76	    @NonNull
77	    public static List<PluginWrapper.Dependency> getImpliedDependencies(String pluginName, String jenkinsVersion) {
78	        List<PluginWrapper.Dependency> out = new ArrayList<>();
79	        for (DetachedPlugin detached : getDetachedPlugins()) {
80	            // don't fix the dependency for itself, or else we'll have a cycle
81	            if (detached.shortName.equals(pluginName)) {
82	                continue;
83	            }
84	            if (BREAK_CYCLES.contains(pluginName + ' ' + detached.shortName)) {
85	                LOGGER.log(Level.FINE, "skipping implicit dependency {0} → {1}", new Object[]{pluginName, detached.shortName});
86	                continue;
87	            }
88	            // some earlier versions of maven-hpi-plugin apparently puts "null" as a literal in Hudson-Version. watch out for them.
89	            if (jenkinsVersion == null || jenkinsVersion.equals("null") || new VersionNumber(jenkinsVersion).compareTo(detached.splitWhen) <= 0) {
90	                out.add(new PluginWrapper.Dependency(detached.shortName + ':' + detached.requiredVersion + ";resolution:=optional"));
91	                LOGGER.log(Level.FINE, "adding implicit dependency {0} → {1} because of {2}",
92	                           new Object[]{pluginName, detached.shortName, jenkinsVersion});
93	            }
94	        }
95	        return out;
96	    }
97	
98	    /**
99	     * Get the list of all plugins that have ever been {@link DetachedPlugin detached} from Jenkins core.
100	     *
101	     * @return A {@link List} of {@link DetachedPlugin}s.
102	     */
103	    public static @NonNull
104	    List<DetachedPlugin> getDetachedPlugins() {
105	        return List.copyOf(DETACHED_LIST);
106	    }
107	
108	    /**
109	     * Get the list of plugins that have been detached since a specific Jenkins release version.
110	     *
111	     * @param since The Jenkins version.
112	     * @return A {@link List} of {@link DetachedPlugin}s.
113	     * @see #getDetachedPlugins()
114	     */
115	    public static @NonNull
116	    List<DetachedPlugin> getDetachedPlugins(@NonNull VersionNumber since) {
117	        return getDetachedPlugins().stream()
118	                .filter(detachedPlugin -> !detachedPlugin.getSplitWhen().isOlderThan(since))
119	                .collect(Collectors.toList());
120	    }
121	
122	    /**
123	     * Is the named plugin a plugin that was detached from Jenkins at some point in the past.
124	     *
125	     * @param pluginId The plugin ID.
126	     * @return {@code true} if the plugin is a plugin that was detached from Jenkins at some
127	     * point in the past, otherwise {@code false}.
128	     */
129	    public static boolean isDetachedPlugin(@NonNull String pluginId) {
130	        for (DetachedPlugin detachedPlugin : getDetachedPlugins()) {
131	            if (detachedPlugin.getShortName().equals(pluginId)) {
132	                return true;
133	            }
134	        }
135	
136	        return false;
137	    }
138	
139	    public static Stream<String> configLines(InputStream is) throws IOException {
140	        return IOUtils.readLines(is, StandardCharsets.UTF_8).stream().filter(line -> !line.matches("#.*|\\s*"));
141	    }
142	
143	    /**
144	     * Information about plugins that were originally in the core.
145	     * <p>
146	     * A detached plugin is one that has any of the following characteristics:
147	     * <ul>
148	     * <li>
149	     * Was an existing plugin that at some time previously bundled with the Jenkins war file.
150	     * </li>
151	     * <li>
152	     * Was previous code in jenkins core that was split to a separate-plugin (but may not have
153	     * ever been bundled in a jenkins war file - i.e. it gets split after this 2.0 update).
154	     * </li>
155	     * </ul>
156	     */
157	    @Restricted(NoExternalUse.class)
158	    public static final class DetachedPlugin {
159	        private final String shortName;
160	        /**
161	         * Plugins built for this Jenkins version (and earlier) will automatically be assumed to have
162	         * this plugin in its dependency.
163	         * <p>
164	         * When core/pom.xml version is 1.123-SNAPSHOT when the code is removed, then this value should
165	         * be "1.123.*" (because 1.124 will be the first version that doesn't include the removed code.)
166	         */
167	        private final VersionNumber splitWhen;
168	        private final String requiredVersion;
169	
170	        private DetachedPlugin(String shortName, String splitWhen, String requiredVersion) {
171	            this.shortName = shortName;
172	            this.splitWhen = new VersionNumber(splitWhen);
173	            this.requiredVersion = requiredVersion;
174	        }
175	
176	        /**
177	         * Get the short name of the plugin.
178	         *
179	         * @return The short name of the plugin.
180	         */
181	        public String getShortName() {
182	            return shortName;
183	        }
184	
185	        /**
186	         * Get the Jenkins version from which the plugin was detached.
187	         *
188	         * @return The Jenkins version from which the plugin was detached.
189	         */
190	        public VersionNumber getSplitWhen() {
191	            return splitWhen;
192	        }
193	
194	        /**
195	         * Gets the minimum required version for the current version of Jenkins.
196	         *
197	         * @return the minimum required version for the current version of Jenkins.
198	         * @since 2.16
199	         */
200	        public VersionNumber getRequiredVersion() {
201	            return new VersionNumber(requiredVersion);
202	        }
203	
204	        @Override
205	        public String toString() {
206	            return shortName + " " + splitWhen.toString().replace(".*", "") + " " + requiredVersion;
207	        }
208	    }
209	}

