217	            // make sure AWT is functioning, or else JFreeChart won't even load.
218	            if (ChartUtil.awtProblemCause != null) {
219	                throw new AWTProblem(ChartUtil.awtProblemCause);
220	            }
221	
222	            // some containers (in particular Tomcat) doesn't abort a launch
223	            // even if the temp directory doesn't exist.
224	            // check that and report an error
225	            try {
226	                File f = File.createTempFile("test", "test");
227	                boolean result = f.delete();
228	                if (!result) {
229	                    LOGGER.log(FINE, "Temp file test.test could not be deleted.");
230	                }
231	            } catch (IOException e) {
232	                throw new NoTempDir(e);
233	            }
234	
235	            installExpressionFactory(event);
236	
237	            context.setAttribute(APP, new HudsonIsLoading());
238	            if (SystemProperties.getBoolean(FORCE_SESSION_TRACKING_BY_COOKIE_PROP, true)) {
239	                context.setSessionTrackingModes(EnumSet.of(SessionTrackingMode.COOKIE));
240	            }
241	
242	            final File _home = home;
243	            initThread = new Thread("Jenkins initialization thread") {
244	                @Override
245	                public void run() {
246	                    boolean success = false;
247	                    try {
248	                        Jenkins instance = new Hudson(_home, context);
249	
250	                        // one last check to make sure everything is in order before we go live
251	                        if (Thread.interrupted())
252	                            throw new InterruptedException();
253	
254	                        context.setAttribute(APP, instance);
255	
256	                        Files.deleteIfExists(BootFailure.getBootFailureFile(_home).toPath());
257	
258	                        // at this point we are open for business and serving requests normally
259	                        Jenkins.get().getLifecycle().onReady();
260	                        success = true;
261	                    } catch (Error e) {
262	                        new HudsonFailedToLoad(e).publish(context, _home);
263	                        throw e;
264	                    } catch (Exception e) {
265	                        // Allow plugins to override error page on boot with custom BootFailure subclass thrown
266	                        Throwable error = unwrapException(e);
267	                        if (error instanceof InvocationTargetException) {
268	                            Throwable targetException = ((InvocationTargetException) error).getTargetException();
269	
270	                            if (targetException instanceof BootFailure) {
271	                                ((BootFailure) targetException).publish(context, _home);
272	                            } else {
273	                                new HudsonFailedToLoad(e).publish(context, _home);
274	                            }
275	                        } else {
276	                            new HudsonFailedToLoad(e).publish(context, _home);
277	                        }
278	                    } finally {
279	                        Jenkins instance = Jenkins.getInstanceOrNull();
280	                        if (!success && instance != null)
281	                            instance.cleanUp();
282	                    }
283	                }
284	
285	                private Throwable unwrapException(Exception e) {
286	                    Throwable error = e;
287	                    while (error.getCause() != null) {
288	                        if (error.getCause() instanceof InvocationTargetException) {
289	                            return error.getCause();
290	                        }
291	                        error = error.getCause();
292	                    }
293	                    return error;
294	                }
295	            };
296	            initThread.start();
297	        } catch (BootFailure e) {
298	            e.publish(context, home);
299	        } catch (Error | RuntimeException e) {
300	            LOGGER.log(SEVERE, "Failed to initialize Jenkins", e);
301	            throw e;
302	        }
303	    }
304	
305	    public void joinInit() throws InterruptedException {
306	        initThread.join();
307	    }
