80	    /**
81	     * Auto-completes possible job names.
82	     *
83	     * @param type
84	     *      Limit the auto-completion to the subtype of this type.
85	     * @param value
86	     *      The value the user has typed in. Matched as a prefix.
87	     * @param self
88	     *      The contextual item for which the auto-completion is provided to.
89	     *      For example, if you are configuring a job, this is the job being configured.
90	     * @param container
91	     *      The nearby contextual {@link ItemGroup} to resolve relative job names from.
92	     * @since 1.489
93	     */
94	    public static <T extends Item> AutoCompletionCandidates ofJobNames(final Class<T> type, final String value, @CheckForNull Item self, ItemGroup container) {
95	        if (self == container)
96	            container = self.getParent();
97	        return ofJobNames(type, value, container);
98	    }
