101	    /**
102	     * Auto-completes possible job names.
103	     *
104	     * @param type
105	     *      Limit the auto-completion to the subtype of this type.
106	     * @param value
107	     *      The value the user has typed in. Matched as a prefix.
108	     * @param container
109	     *      The nearby contextual {@link ItemGroup} to resolve relative job names from.
110	     * @since 1.553
111	     */
112	    @SuppressFBWarnings(value = "SBSC_USE_STRINGBUFFER_CONCATENATION", justification = "no big deal")
113	    public static  <T extends Item> AutoCompletionCandidates ofJobNames(final Class<T> type, final String value, ItemGroup container) {
114	        final AutoCompletionCandidates candidates = new AutoCompletionCandidates();
115	        class Visitor extends ItemVisitor {
116	            String prefix;
117	
118	            Visitor(String prefix) {
119	                this.prefix = prefix;
120	            }
121	
122	            @Override
123	            public void onItem(Item i) {
124	                String itemName = contextualNameOf(i);
125	
126	                //Check user's setting on whether to do case sensitive comparison, configured in user -> configure
127	                //This is the same setting that is used by the global search field, should be consistent throughout
128	                //the whole application.
129	                boolean caseInsensitive = UserSearchProperty.isCaseInsensitive();
130	
131	                if ((startsWithImpl(itemName, value, caseInsensitive) || startsWithImpl(value, itemName, caseInsensitive))
132	                    // 'foobar' is a valid candidate if the current value is 'foo'.
133	                    // Also, we need to visit 'foo' if the current value is 'foo/bar'
134	                 && (value.length() > itemName.length() || !itemName.substring(value.length()).contains("/"))
135	                    // but 'foobar/zot' isn't if the current value is 'foo'
136	                    // we'll first show 'foobar' and then wait for the user to type '/' to show the rest
137	                 && i.hasPermission(Item.READ)
138	                    // and read permission required
139	                ) {
140	                    if (type.isInstance(i) && startsWithImpl(itemName, value, caseInsensitive))
141	                        candidates.add(itemName);
142	
143	                    // recurse
144	                    String oldPrefix = prefix;
145	                    prefix = itemName;
146	                    super.onItem(i);
147	                    prefix = oldPrefix;
148	                }
149	            }
150	
151	            private String contextualNameOf(Item i) {
152	                if (prefix.endsWith("/") || prefix.isEmpty())
153	                    return prefix + i.getName();
154	                else
155	                    return prefix + '/' + i.getName();
156	            }
157	        }
158	
159	        if (container == null || container == Jenkins.get()) {
160	            new Visitor("").onItemGroup(Jenkins.get());
161	        } else {
162	            new Visitor("").onItemGroup(container);
163	            if (value.startsWith("/"))
164	                new Visitor("/").onItemGroup(Jenkins.get());
165	
166	            for (String p = "../"; value.startsWith(p); p += "../") {
167	                container = ((Item) container).getParent();
168	                new Visitor(p).onItemGroup(container);
169	            }
170	        }
171	
172	        return candidates;
173	    }
174	
175	    private static boolean startsWithImpl(String str, String prefix, boolean ignoreCase) {
176	        return ignoreCase ? str.toLowerCase(Locale.ROOT).startsWith(prefix.toLowerCase(Locale.ROOT)) : str.startsWith(prefix);
177	    }
178	}

