38	/**
39	 * CLI Command, which puts the Jenkins node offline.
40	 * @author pjanouse
41	 * @since 2.15
42	 */
43	@Extension
44	public class OfflineNodeCommand extends CLICommand {
45	
46	    @Argument(metaVar = "NAME", usage = "Agent name, or empty string for built-in node", required = true, multiValued = true)
47	    private List<String> nodes;
48	
49	    @Option(name = "-m", usage = "Record the reason about why you are disconnecting this node")
50	    public String cause;
51	
52	    @Override
53	    public String getShortDescription() {
54	        return Messages.OfflineNodeCommand_ShortDescription();
55	    }
56	
57	    @Override
58	    protected int run() throws Exception {
59	        boolean errorOccurred = false;
60	        final Jenkins jenkins = Jenkins.get();
61	        final HashSet<String> hs = new HashSet<>(nodes);
62	        List<String> names = null;
63	
64	        for (String node_s : hs) {
65	            try {
66	                Computer computer = jenkins.getComputer(node_s);
67	                if (computer == null) {
68	                    if (names == null) {
69	                        names = ComputerSet.getComputerNames();
70	                    }
71	                    String adv = EditDistance.findNearest(node_s, names);
72	                    throw new IllegalArgumentException(adv == null ?
73	                            hudson.model.Messages.Computer_NoSuchSlaveExistsWithoutAdvice(node_s) :
74	                            hudson.model.Messages.Computer_NoSuchSlaveExists(node_s, adv));
75	                }
76	                computer.cliOffline(cause);
77	            } catch (Exception e) {
78	                if (hs.size() == 1) {
79	                    throw e;
80	                }
81	
82	                stderr.println(node_s + ": " + e.getMessage());
83	                errorOccurred = true;
84	                continue;
85	            }
86	        }
87	
88	        if (errorOccurred) {
89	            throw new AbortException(CLI_LISTPARAM_SUMMARY_ERROR_TEXT);
90	        }
91	        return 0;
92	    }
93	}

