39	import java.util.concurrent.locks.ReentrantReadWriteLock;
40	import net.jcip.annotations.GuardedBy;
41	
42	/**
43	 * A {@link Queue.QueueDecisionHandler} that blocks items being deleted from entering the queue.
44	 *
45	 * @since 2.55
46	 */
47	@Extension
48	public class ItemDeletion extends Queue.QueueDecisionHandler {
49	
50	    /**
51	     * Lock to guard the {@link #registrations} set.
52	     */
53	    private final ReadWriteLock lock = new ReentrantReadWriteLock();
54	    /**
55	     * The explicit deletions in progress.
56	     */
57	    @GuardedBy("lock")
58	    private final Set<Item> registrations = new HashSet<>();
59	
60	    @GuardedBy("lock")
61	    private boolean _contains(@NonNull Item item) {
62	        if (registrations.isEmpty()) {
63	            // no point walking everything if there is nothing in-flight
64	            return false;
65	        }
66	
67	        while (item != null) {
68	            if (registrations.contains(item)) {
69	                return true;
70	            }
71	            if (item.getParent() instanceof Item) {
72	                item = (Item) item.getParent();
73	            } else {
74	                break;
75	            }
76	        }
77	        return false;
78	    }
79	
80	    /**
81	     * Checks if the supplied {@link Item} or any of its {@link Item#getParent()} are being deleted.
82	     *
83	     * @param item the item.
84	     * @return {@code true} if the {@link Item} or any of its {@link Item#getParent()} are being deleted.
85	     */
86	    public static boolean contains(@NonNull Item item) {
87	        ItemDeletion instance = instance();
88	        if (instance == null) {
89	            return false;
90	        }
91	        instance.lock.readLock().lock();
92	        try {
93	            return instance._contains(item);
94	        } finally {
95	            instance.lock.readLock().unlock();
96	        }
97	    }
98	
99	    /**
100	     * Checks if the supplied {@link Item} is explicitly registered for deletion.
101	     *
102	     * @param item the item.
103	     * @return {@code true} if and only if the supplied {@link Item} has been {@linkplain #register(Item)}ed for
104	     * deletion.
105	     */
106	    public static boolean isRegistered(@NonNull Item item) {
107	        ItemDeletion instance = instance();
108	        if (instance == null) {
109	            return false;
110	        }
111	        instance.lock.readLock().lock();
112	        try {
113	            return instance.registrations.contains(item);
114	        } finally {
115	            instance.lock.readLock().unlock();
116	        }
117	    }
118	
119	    /**
120	     * Register the supplied {@link Item} for deletion.
121	     *
122	     * @param item the {@link Item} that is to be deleted.
123	     * @return {@code true} if and only if the {@link Item} was registered and the caller is now responsible to call
124	     * {@link #deregister(Item)}.
125	     */
126	    public static boolean register(@NonNull Item item) {
127	        ItemDeletion instance = instance();
128	        if (instance == null) {
129	            return false;
130	        }
131	        instance.lock.writeLock().lock();
132	        try {
133	            return instance.registrations.add(item);
134	        } finally {
135	            instance.lock.writeLock().unlock();
136	        }
137	    }
138	
139	    /**
140	     * Deregister the supplied {@link Item} for deletion.
141	     *
142	     * @param item the {@link Item} that was to be deleted and is now either deleted or the delete was aborted.
143	     */
144	    public static void deregister(@NonNull Item item) {
145	        ItemDeletion instance = instance();
146	        if (instance != null) {
147	            instance.lock.writeLock().lock();
148	            try {
149	                instance.registrations.remove(item);
150	            } finally {
151	                instance.lock.writeLock().unlock();
152	            }
153	        }
154	    }
155	
156	    /**
157	     * Gets the singleton instance.
158	     *
159	     * @return the {@link ItemDeletion} singleton.
160	     */
161	    @CheckForNull
162	    private static ItemDeletion instance() {
163	        return ExtensionList.lookup(Queue.QueueDecisionHandler.class).get(ItemDeletion.class);
164	    }
165	
166	    @Override
167	    public boolean shouldSchedule(Queue.Task p, List<Action> actions) {
168	        Item item = Tasks.getItemOf(p);
169	        if (item != null) {
170	            lock.readLock().lock();
171	            try {
172	                return !_contains(item);
173	            } finally {
174	                lock.readLock().unlock();
175	            }
176	        }
177	        return true;
178	    }
179	}

