414	    /**
415	     * @param req              the request to process
416	     * @param validateCaptcha  whether to attempt to validate a captcha in the request
417	     *
418	     * @return a {@link SignupInfo#SignupInfo(StaplerRequest) SignupInfo from given request}, with {@link
419	     * SignupInfo#errors} containing errors (keyed by field name), if any of the supported fields are invalid
420	     */
421	    @SuppressFBWarnings(value = "UWF_UNWRITTEN_PUBLIC_OR_PROTECTED_FIELD", justification = "written to by Stapler")
422	    private SignupInfo validateAccountCreationForm(StaplerRequest req, boolean validateCaptcha) {
423	        // form field validation
424	        // this pattern needs to be generalized and moved to stapler
425	        SignupInfo si = new SignupInfo(req);
426	
427	        if (validateCaptcha && !validateCaptcha(si.captcha)) {
428	            si.errors.put("captcha", Messages.HudsonPrivateSecurityRealm_CreateAccount_TextNotMatchWordInImage());
429	        }
430	
431	        if (si.username == null || si.username.isEmpty()) {
432	            si.errors.put("username", Messages.HudsonPrivateSecurityRealm_CreateAccount_UserNameRequired());
433	        } else if (!containsOnlyAcceptableCharacters(si.username)) {
434	            if (ID_REGEX == null) {
435	                si.errors.put("username", Messages.HudsonPrivateSecurityRealm_CreateAccount_UserNameInvalidCharacters());
436	            } else {
437	                si.errors.put("username", Messages.HudsonPrivateSecurityRealm_CreateAccount_UserNameInvalidCharactersCustom(ID_REGEX));
438	            }
439	        } else {
440	            // do not create the user - we just want to check if the user already exists but is not a "login" user.
441	            User user = User.getById(si.username, false);
442	            if (null != user)
443	                // Allow sign up. SCM people has no such property.
444	                if (user.getProperty(Details.class) != null)
445	                    si.errors.put("username", Messages.HudsonPrivateSecurityRealm_CreateAccount_UserNameAlreadyTaken());
446	        }
447	
448	        if (si.password1 != null && !si.password1.equals(si.password2)) {
449	            si.errors.put("password1", Messages.HudsonPrivateSecurityRealm_CreateAccount_PasswordNotMatch());
450	        }
451	
452	        if (!(si.password1 != null && si.password1.length() != 0)) {
453	            si.errors.put("password1", Messages.HudsonPrivateSecurityRealm_CreateAccount_PasswordRequired());
454	        }
455	
456	        if (FIPS140.useCompliantAlgorithms()) {
457	            if (si.password1.length() < FIPS_PASSWORD_LENGTH) {
458	                si.errors.put("password1", Messages.HudsonPrivateSecurityRealm_CreateAccount_FIPS_PasswordLengthInvalid());
459	            }
460	        }
461	        if (si.fullname == null || si.fullname.isEmpty()) {
462	            si.fullname = si.username;
463	        }
464	
465	        if (isMailerPluginPresent() && (si.email == null || !si.email.contains("@"))) {
466	            si.errors.put("email", Messages.HudsonPrivateSecurityRealm_CreateAccount_InvalidEmailAddress());
467	        }
468	
469	        if (!User.isIdOrFullnameAllowed(si.username)) {
470	            si.errors.put("username", hudson.model.Messages.User_IllegalUsername(si.username));
471	        }
472	
473	        if (!User.isIdOrFullnameAllowed(si.fullname)) {
474	            si.errors.put("fullname", hudson.model.Messages.User_IllegalFullname(si.fullname));
475	        }
476	        req.setAttribute("data", si); // for error messages in the view
477	        return si;
478	    }
