480	    /**
481	     * Creates a new account from a valid signup info. A signup info is valid if its {@link SignupInfo#errors}
482	     * field is empty.
483	     *
484	     * @param si the valid signup info to create an account from
485	     * @return a valid {@link User} object created from given signup info
486	     * @throws IllegalArgumentException if an invalid signup info is passed
487	     */
488	    private User createAccount(SignupInfo si) throws IOException {
489	        if (!si.errors.isEmpty()) {
490	            String messages = getErrorMessages(si);
491	            throw new IllegalArgumentException("invalid signup info passed to createAccount(si): " + messages);
492	        }
493	        // register the user
494	        User user = createAccount(si.username, si.password1);
495	        user.setFullName(si.fullname);
496	        if (isMailerPluginPresent()) {
497	            try {
498	                // legacy hack. mail support has moved out to a separate plugin
499	                Class<?> up = Jenkins.get().pluginManager.uberClassLoader.loadClass("hudson.tasks.Mailer$UserProperty");
500	                Constructor<?> c = up.getDeclaredConstructor(String.class);
501	                user.addProperty((UserProperty) c.newInstance(si.email));
502	            } catch (ReflectiveOperationException e) {
503	                throw new RuntimeException(e);
504	            }
505	        }
506	        user.save();
507	        return user;
508	    }
