510	    private boolean containsOnlyAcceptableCharacters(@NonNull String value) {
511	        if (ID_REGEX == null) {
512	            return value.matches(DEFAULT_ID_REGEX);
513	        } else {
514	            return value.matches(ID_REGEX);
515	        }
516	    }
