936	function makeButton(e, onclick) {
937	  var h = e.onclick;
938	  var clsName = e.className;
939	  var n = e.name;
940	
941	  var attributes = {};
942	  // YUI Button class interprets value attribute of <input> as HTML
943	  // similar to how the child nodes of a <button> are treated as HTML.
944	  // in standard HTML, we wouldn't expect the former case, yet here we are!
945	  if (e.tagName === "INPUT") {
946	    attributes.label = escapeHTML(e.value);
947	  }
948	  var btn = new YAHOO.widget.Button(e, attributes);
949	  if (onclick != null) {
950	    btn.addListener("click", onclick);
951	  }
952	  if (h != null) {
953	    btn.addListener("click", h);
954	  }
955	  var be = btn.get("element");
956	  var classesSeparatedByWhitespace = clsName.split(" ");
957	  for (let i = 0; i < classesSeparatedByWhitespace.length; i++) {
958	    var singleClass = classesSeparatedByWhitespace[i];
959	    if (singleClass) {
960	      be.classList.add(singleClass);
961	    }
962	  }
963	  if (n) {
964	    // copy the name
965	    be.setAttribute("name", n);
966	  }
967	
968	  // keep the data-* attributes from the source
969	  var length = e.attributes.length;
970	  for (let i = 0; i < length; i++) {
971	    var attribute = e.attributes[i];
972	    var attributeName = attribute.name;
973	    if (attributeName.startsWith("data-")) {
974	      btn._button.setAttribute(attributeName, attribute.value);
975	    }
976	  }
977	  return btn;
978	}
